using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Users;[Authorize(Policy="SuperAdminOnly")]public sealed class EditModel(OrcaFacilDbContext db):PageModel{public View UserView{get;private set;}=default!;public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){var u=await db.Users.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted,ct);if(u is null)return NotFound();var accounts=await(from m in db.AccountMembers.AsNoTracking()join a in db.BusinessAccounts.AsNoTracking()on m.AccountId equals a.Id where m.UserId==id&&!m.IsDeleted&&!a.IsDeleted select a.DisplayName+" · "+m.RoleCode).ToListAsync(ct);UserView=new(u.Id,u.Name,u.Email,u.Role.ToString(),accounts);return Page();}public Task<IActionResult>OnPostBlockAsync(Guid id,string reason,CancellationToken ct)=>Change(id,ct,u=>{u.IsBlocked=true;u.BlockReason=reason;u.RevokeSessions();},"GlobalUserBlocked",reason);public Task<IActionResult>OnPostReactivateAsync(Guid id,CancellationToken ct)=>Change(id,ct,u=>{u.IsBlocked=false;u.IsActive=true;u.BlockReason=null;u.RevokeSessions();},"GlobalUserReactivated","Usuário reativado.");public Task<IActionResult>OnPostDeleteAsync(Guid id,CancellationToken ct)=>Change(id,ct,u=>{u.MarkAsDeleted();u.IsActive=false;u.RevokeSessions();},"GlobalUserSoftDeleted","Exclusão lógica executada.");private async Task<IActionResult>Change(Guid id,CancellationToken ct,Action<UserAccount>change,string action,string summary){var u=await db.Users.SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted,ct);if(u is null)return NotFound();change(u);db.AccountModuleAuditLogs.Add(new(){ActorUserId=Guid.TryParse(User.FindFirstValue("user_id"),out var a)?a:Guid.Empty,Action=action,EntityType=nameof(UserAccount),EntityId=id.ToString(),Summary=summary,CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return action.EndsWith("Deleted")?RedirectToPage("Index"):RedirectToPage(new{id});}public sealed record View(Guid Id,string Name,string Email,string Role,IReadOnlyList<string>Accounts);}
